{
  "avaliacoes": [
    {
      "id": "E2d81a6a16a58e987",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O guia de inspeção foi elaborado para apoiar inspeções de cibersegurança em IACS de instalações offshore do UKCS, cobrindo instalações reguladas e não reguladas pelo regime NIS, com abordagem proporcional e direcionada.",
          "trechos": [
            "E2d81a6a16a58e987:0:698",
            "E2d81a6a16a58e987:698:1391"
          ],
          "condicoes": [
            "no contexto regulatório do Reino Unido e do UK Continental Shelf",
            "aplica-se a inspeções conduzidas por inspetores do OSDR/HSE"
          ],
          "limites": [
            "é material de inspeção e orientação regulatória estrangeira, não requisito brasileiro",
            "o trecho não detalha procedimentos operacionais de resposta a incidentes, contenção ou erradicação"
          ]
        },
        {
          "proposicao": "As inspeções subsequentes e as não abrangidas pela categoria inicial são selecionadas por categorias e por uma matriz de seleção de inspeção, indicando critério de direcionamento e priorização das verificações de cibersegurança.",
          "trechos": [
            "E2d81a6a16a58e987:698:1391",
            "E2d81a6a16a58e987:1391:2091"
          ],
          "condicoes": [
            "no processo de inspeção descrito pelo próprio guia",
            "para instalações NIS e não NIS no escopo indicado"
          ],
          "limites": [
            "o trecho não explicita critérios técnicos detalhados de seleção por tipos de anomalia, logs ou eventos",
            "priorização regulatória não equivale a procedimento interno de resposta a incidentes"
          ]
        },
        {
          "proposicao": "O objetivo primário do guia e da referência OG86 é verificar a adequação do sistema de gestão de cibersegurança de IACS, incluindo gestão de competências e efetividade de contramedidas, em locais com potencial de acidente maior e operadores de serviços essenciais.",
          "trechos": [
            "E2d81a6a16a58e987:1391:2091",
            "E2d81a6a16a58e987:2091:2518"
          ],
          "condicoes": [
            "no âmbito das inspeções de cibersegurança descritas",
            "para sistemas IACS nos locais e operadores cobertos pelas regulações citadas"
          ],
          "limites": [
            "o trecho não identifica quais contramedidas devem ser adotadas nem como medir sua eficácia operacional em incidentes específicos",
            "a menção a gestão e contramedidas não substitui evidência empírica de desempenho em eventos reais"
          ]
        }
      ]
    },
    {
      "id": "Ea3d79d3ac748d62d",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "No escopo descrito, IACS inclui sistemas básicos de controle de processo, funções de camadas independentes de proteção, sistemas de segurança, sistemas elétricos de controle e aquisição de dados e sistemas de informação e de negócios associados conectados pela infraestrutura de rede do IACS.",
          "trechos": [
            "Ea3d79d3ac748d62d:0:700",
            "Ea3d79d3ac748d62d:700:1390"
          ],
          "condicoes": [
            "no enquadramento do guia HSE/OG86",
            "para locais com riscos maiores e serviços essenciais cobertos pelo documento"
          ],
          "limites": [
            "é definição de escopo para inspeção, não descrição de arquitetura mandatória universal",
            "não detalha mecanismos de logs, detecção de malware ou fluxo de tratamento de incidentes"
          ]
        },
        {
          "proposicao": "Para offshore, o escopo pode incluir também sistemas marítimos, de perfuração e de monitoramento de movimento de helicópteros, ampliando a interface entre cibersegurança de IACS e funções operacionais críticas além do controle de processo.",
          "trechos": [
            "Ea3d79d3ac748d62d:700:1390"
          ],
          "condicoes": [
            "apenas para o contexto offshore mencionado no guia"
          ],
          "limites": [
            "o trecho usa formulação de inclusão possível no escopo, não afirma presença necessária em toda instalação",
            "não há detalhamento sobre monitoramento de eventos ou resposta para cada subsistema citado"
          ]
        },
        {
          "proposicao": "Para instalações reguladas por NIS, o processo descrito exige autoavaliação de cibersegurança baseada no CAF do NCSC, com indicadores de boas práticas, análise de lacunas, perfil-alvo e plano de ação; a inspeção usa essa saída como ponto de partida para amostragem dos objetivos, princípios e resultados.",
          "trechos": [
            "Ea3d79d3ac748d62d:1390:2090",
            "Ea3d79d3ac748d62d:2090:2378"
          ],
          "condicoes": [
            "no regime NIS citado e perante a autoridade competente descrita",
            "quando o operador de serviço essencial estiver sujeito ao processo de autoavaliação"
          ],
          "limites": [
            "trata-se de arranjo regulatório do Reino Unido",
            "o trecho não informa conteúdo detalhado do CAF nem converte seus indicadores em requisitos brasileiros",
            "análise de lacunas e plano de ação não equivalem, por si, a procedimento completo de contenção, erradicação e recuperação"
          ]
        }
      ]
    },
    {
      "id": "E68ff9b835100fc73",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O guia de segurança funcional trata a segurança funcional como componente-chave do conjunto de medidas para minimizar risco e prevenir eventos perigosos com potencial impacto a pessoas ou ao meio ambiente.",
          "trechos": [
            "E68ff9b835100fc73:0:699"
          ],
          "condicoes": [
            "no contexto de inspeções de segurança funcional e conformidade com a referência citada"
          ],
          "limites": [
            "o foco principal é segurança funcional, não monitoramento cibernético",
            "não descreve eventos, logs ou malware"
          ]
        },
        {
          "proposicao": "O documento relaciona a inspeção de segurança funcional com outros temas operacionais relevantes, incluindo gestão de alarmes, overrides e inhibits e avaliação de risco operacional em condições anormais, sugerindo interface entre desempenho de sistemas instrumentados e resposta a condições de desvio.",
          "trechos": [
            "E68ff9b835100fc73:699:1396",
            "E68ff9b835100fc73:1396:2085"
          ],
          "condicoes": [
            "como remissão a outros guias de inspeção associados"
          ],
          "limites": [
            "a relação é de referência cruzada entre guias, não de mecanismo técnico detalhado",
            "o trecho não especifica como integrar resposta a incidente cibernético com emergência operacional"
          ]
        },
        {
          "proposicao": "O guia remete explicitamente ao guia de inspeção de Cyber Security for IACS para avaliação de como a gestão de risco cibernético seria inspecionada, indicando complementaridade entre segurança funcional e cibersegurança em sistemas de proteção instrumentada.",
          "trechos": [
            "E68ff9b835100fc73:1396:2085"
          ],
          "condicoes": [
            "na atividade de inspeção e demonstração de conformidade tratada pelo documento"
          ],
          "limites": [
            "a remissão não fornece por si só critérios de detecção, contenção ou erradicação",
            "não demonstra empiricamente efeitos de incidentes cibernéticos sobre SIF ou SIS"
          ]
        }
      ]
    },
    {
      "id": "Ee508666b790e7ceb",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Uma série de falhas em sistemas UPS industriais foi associada a perda significativa de energia para sistemas de controle industrial, sistemas de shutdown de emergência e sistemas de mitigação de emergência, comprometendo a confiabilidade e efetividade desses sistemas críticos.",
          "trechos": [
            "Ee508666b790e7ceb:0:699"
          ],
          "condicoes": [
            "nos incidentes de que a BSEE tomou conhecimento",
            "relacionado ao contexto de falta de manutenção em UPS indicado no alerta"
          ],
          "limites": [
            "é alerta baseado em incidentes reportados, não regra universal para toda instalação",
            "não trata de malware nem de incidente cibernético deliberado",
            "jurisdição e enquadramento são dos EUA"
          ]
        },
        {
          "proposicao": "Em um dos incidentes, após falha da UPS com fumaça e arco elétrico, os disjuntores de alimentação foram abertos e bloqueados e o sistema foi colocado em safe bypass para manter alimentação de equipamentos críticos enquanto se realizava inspeção do dano no inversor.",
          "trechos": [
            "Ee508666b790e7ceb:699:1396",
            "Ee508666b790e7ceb:1396:2096"
          ],
          "condicoes": [
            "após isolamento seguro das partes com falha",
            "para permitir inspeção pelos técnicos e manter suprimento aos equipamentos críticos"
          ],
          "limites": [
            "descreve resposta observada em um incidente específico",
            "não deve ser convertida em procedimento obrigatório geral sem fonte adicional",
            "não há detalhamento sobre critérios de decisão, tempos ou compatibilidade com diferentes arquiteturas"
          ]
        },
        {
          "proposicao": "Em outro incidente, durante atividades de teste em instalação offshore, a ativação de sistema de segurança de emergência causou perda de geração e shutdown, seguida por deluge total das zonas e alarme de abandono; simultaneamente o gerador de emergência não partiu e a UPS não forneceu potência de backup como esperado, evidenciando forte interface entre falhas elétricas e emergência operacional.",
          "trechos": [
            "Ee508666b790e7ceb:1396:2096",
            "Ee508666b790e7ceb:2096:2360"
          ],
          "condicoes": [
            "durante atividades de teste na instalação offshore citada"
          ],
          "limites": [
            "relato de incidente singular dentro do alerta",
            "não descreve investigação de causa raiz completa nem recuperação posterior",
            "não é evidência específica de cenário FPSO"
          ]
        }
      ]
    },
    {
      "id": "E55b8a6205c6a682e",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Aplicações de gerenciamento de alarmes do SCADA são apontadas como necessárias para entender e otimizar múltiplos eventos produzidos por múltiplos controladores de campo.",
          "trechos": [
            "E55b8a6205c6a682e:0:696"
          ],
          "condicoes": [
            "no contexto arquitetural descrito para SCADA e controladores de campo"
          ],
          "limites": [
            "o trecho é descritivo e não detalha método de correlação, priorização ou resposta a alarmes",
            "a fonte tem fronteiras documentais indeterminadas"
          ]
        },
        {
          "proposicao": "Um historiador de séries temporais pode ser usado para armazenar dados, enquanto HMIs com desenho voltado à consciência situacional fornecem a interface ao usuário, compondo base técnica útil para monitoramento operacional.",
          "trechos": [
            "E55b8a6205c6a682e:0:696"
          ],
          "condicoes": [
            "na arquitetura descrita no trecho"
          ],
          "limites": [
            "o texto não afirma que isso seja suficiente para detecção de incidentes cibernéticos",
            "não há critérios de retenção, integridade de logs ou investigação forense"
          ]
        },
        {
          "proposicao": "A diversidade de modelos de dados entre controladores de diferentes fornecedores dificulta convenções de nomenclatura, padronização de HMI e comparação entre ativos; como a padronização no nível de controle é limitada, o SCADA é apresentado como o nível mais próximo da fonte de dados onde isso pode ser feito, e a padronização é desejável para viabilizar análise.",
          "trechos": [
            "E55b8a6205c6a682e:0:696",
            "E55b8a6205c6a682e:696:1394"
          ],
          "condicoes": [
            "quando coexistem diferentes mapas de dados de controladores e modelos customizados"
          ],
          "limites": [
            "o trecho trata de análise e padronização de dados, não de contenção, erradicação ou malware",
            "não demonstra empiricamente impacto direto sobre desempenho de resposta a incidentes"
          ]
        }
      ]
    },
    {
      "id": "E8f3874e2bdb0193c",
      "pertinente": false,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte aborda integração funcional entre controle de bombeio, RTU, telemetria, SCADA, IIOT e aplicações de software para otimização e monitoramento remoto.",
          "trechos": [
            "E8f3874e2bdb0193c:0:700",
            "E8f3874e2bdb0193c:700:1400"
          ],
          "condicoes": [
            "no contexto de soluções de artificial lift descritas"
          ],
          "limites": [
            "não trata diretamente de eventos, logs, anomalias, malware, contenção, erradicação ou resposta a incidentes",
            "o cenário é de poço/bombeio e não especificamente de FPSO"
          ]
        }
      ]
    }
  ],
